using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"), Description("Returns current application configuration")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/endpoints", Name = "API Endpoints",
        MimeType = "application/json"), Description("Returns configured API endpoint URLs")]
    public static string GetEndpoints()
    {
        var endpoints = new
        {
            Auth = "https://auth.example.com/v2",
            Data = "https://api.example.com/v1",
            Storage = "https://storage.example.com"
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Updates a configuration value by key.")]
    public static string UpdateConfig(
        [Description("The configuration key to update")] string key,
        [Description("The new value to set")] string value)
    {
        // In production, persist to a config store
        return $"Configuration '{key}' updated to '{value}'.";
    }

    [McpServerTool, Description("Validates the current configuration for consistency.")]
    public static string ValidateConfig()
    {
        return "Configuration is valid. All required keys are present and values are within acceptable ranges.";
    }
}

